if (countBadge) countBadge.innerText = `${total.toLocaleString()} အုပ်`;
if (!searchQuery && activeCategory === 'ALL' && total > 0) {
  const mmDigits = ['၀','၁','၂','၃','၄','၅','၆','၇','၈','၉'];
