    const params = new URLSearchParams({
      category: activeCategory,
      q: searchQuery,
      sort: currentSort,
      page: currentPage,
      limit: pageSize
    });

    const res = await fetch(`/api/books?${params.toString()}`);
    if (!res.ok) throw new Error(`HTTP error ${res.status}`);
    const data = await res.json();
    const books = data.books || [];
    const total = data.total || 0;

    if (countBadge) countBadge.innerText = `${total.toLocaleString()} အုပ်`;
    if (!searchQuery && activeCategory === 'ALL' && total > 0) {
      const mmDigits = ['၀','၁','၂','၃','၄','၅','၆','၇','၈','၉'];
      const mmTotal = total.toLocaleString().replace(/[0-9]/g, d => mmDigits[parseInt(d, 10)]);
      document.querySelectorAll('.live-total-books').forEach(el => { el.innerText = mmTotal; });
    }

    if (total === 0) {
      grid.innerHTML = '';
      empty?.classList.remove('hidden');
      loadMoreBtn?.classList.add('hidden');
      return;
    }

    empty?.classList.add('hidden');
    loadMoreBtn?.classList.toggle('hidden', (currentPage * pageSize) >= total);

    const cardsHtml = books.map(book => {
      const title = cleanTitle(book.title);
      const jacket = getJacketForBook(book.id);
      const size = formatBytes(book.size);

      const safeTitle = safeEncode(book.title);
      const safeCat = safeEncode(book.category);

      return `
        <div class="group flex flex-col justify-between book-card-animate">
          <div class="editorial-book cursor-pointer" 
               style="background-color: ${jacket.bg}; border: 1px solid ${jacket.border};"
               onclick="openQuickAction(${book.id}, '${safeTitle}', '${safeCat}', ${book.size})">

            <div class="book-inner-frame"></div>

            <div class="z-10 pl-2 pr-1 flex justify-between items-center text-[9px] font-mono text-slate-400">
              <span class="truncate max-w-[90px] uppercase">${book.category}</span>
              <span class="text-[8px] bg-black/40 px-1 py-0.5 rounded border border-white/10">PDF</span>
            </div>

            <div class="z-10 px-2 py-3 my-auto text-center flex flex-col items-center justify-center">
              <h3 class="font-sans book-title-text font-bold text-xs sm:text-[13px] book-cover-title leading-relaxed line-clamp-3">
                ${title}
              </h3>
              <div class="w-8 h-px bg-amber-400/70 mx-auto mt-2.5"></div>
            </div>

            <div class="z-10 pl-2 pr-1 flex items-center justify-between text-[9px] font-mono text-slate-400">
              <span>${size}</span>
              <span class="text-white/90 group-hover:text-amber-300 transition flex items-center gap-0.5 font-medium">
                အစမ်းဖတ် <i data-lucide="arrow-up-right" class="w-2.5 h-2.5 inline"></i>
              </span>
            </div>
          </div>

          <div class="mt-3.5 space-y-2">
            <h4 class="text-xs font-sans book-title-text font-medium book-external-title line-clamp-2 leading-relaxed min-h-[2.5rem] cursor-pointer" 
                onclick="openQuickAction(${book.id}, '${safeTitle}', '${safeCat}', ${book.size})"
                title="${title}">
              ${title}
            </h4>

            <div class="flex items-center gap-2 pt-0.5">
              <button onclick="openDownloadModal(${book.id}, '${safeTitle}', '${safeCat}', ${book.size})" class="flex-1 py-1.5 px-2 bg-[#121622] book-action-btn hover:bg-amber-600 border border-slate-800 hover:border-amber-500 text-slate-200 hover:text-white rounded-lg text-[11px] font-medium transition flex items-center justify-center gap-1.5 shadow-sm">
                <i data-lucide="download" class="w-3 h-3 text-amber-400 group-hover:text-white"></i>
                <span>ဒေါင်းလုဒ်</span>
              </button>

              <button onclick="openQuickAction(${book.id}, '${safeTitle}', '${safeCat}', ${book.size})" title="နမူနာ အစမ်းဖတ်ရှုရန်" class="p-1.5 bg-[#121622] book-action-btn hover:bg-slate-800 border border-slate-800 rounded-lg text-slate-400 hover:text-slate-200 transition">
                <i data-lucide="eye" class="w-3.5 h-3.5"></i>
              </button>
            </div>
          </div>
        </div>
      `;
    }).join('');

    if (isAppend) {
      grid.insertAdjacentHTML('beforeend', cardsHtml);
    } else {
      grid.innerHTML = cardsHtml;
    }

    refreshIcons();
  } catch (err) {
    console.error('Failed to load books:', err);
    grid.innerHTML = `
      <div class="col-span-full py-16 text-center">
        <p class="text-red-400 text-xs mb-3">စာအုပ်များ ခေါ်ယူရာတွင် ချိတ်ဆက်မှု အဆင်မပြေဖြစ်ပါသည် (${err.message})</p>
        <button onclick="fetchAndRenderBooks()" class="px-4 py-1.5 bg-amber-600 hover:bg-amber-500 text-white text-xs rounded-md transition font-medium">
          ပြန်လည်စမ်းသပ်မည် (Retry)
        </button>
      </div>
    `;
  }
}

