async function startDownloadSequence() {
    document.getElementById('dlStateInitial').classList.add('hidden');
    document.getElementById('dlStateLoading').classList.remove('hidden');

    const bar = document.getElementById('dlProgressBar');
    bar.style.width = '0%';

    let progress = 0;
    const interval = setInterval(() => {
        progress += 25;
        bar.style.width = `${progress}%`;

        if (progress >= 100) {
            clearInterval(interval);
            setTimeout(() => {
                const downloadUrl = `/api/download/${selectedBook.id}`;
                triggerBrowserDownload(downloadUrl, selectedBook.title);

                document.getElementById('dlStateLoading').classList.add('hidden');
                document.getElementById('dlStateComplete').classList.remove('hidden');
            }, 250);
        }
    }, 150);
}

let previewLoadTimer = null;

function openPreviewModal(bookId, encodedTitle, encodedCat, size) {
  const title = cleanTitle(decodeURIComponent(encodedTitle));
  const category = decodeURIComponent(encodedCat);
  const sizeFormatted = formatBytes(size);
  selectedBook = { id: bookId, title: decodeURIComponent(encodedTitle), category, size };

  document.getElementById('previewTitle').innerText = title;
  document.getElementById('previewHeaderCategory').innerText = category;
  document.getElementById('previewHeaderSize').innerText = sizeFormatted;

  const previewUrl = `/api/preview/${bookId}`;
  const iframe = document.getElementById('previewIframe');
  const loader = document.getElementById('previewLoader');
  const newTabBtn = document.getElementById('previewNewTabBtn');

  if (newTabBtn) {
    newTabBtn.href = previewUrl;
  }

  if (loader) loader.classList.remove('hidden');
  if (previewLoadTimer) clearTimeout(previewLoadTimer);

  if (iframe) {
    iframe.src = `/static/pdfview/web/viewer.html?v=4&file=${encodeURIComponent(previewUrl)}`;
    iframe.onload = () => {
      try {
        const win = iframe.contentWindow;
        if (win && win.PDFViewerApplication && win.PDFViewerApplication.initializedPromise) {
          win.PDFViewerApplication.initializedPromise.then(() => {
            const eb = win.PDFViewerApplication.eventBus;
            if (eb) {
              const hideLoader = () => { if (loader) loader.classList.add('hidden'); };
              eb.on('pagesinit', hideLoader);
              eb.on('documentloaded', hideLoader);
              eb.on('documenterror', hideLoader);
            } else if (loader) {
              loader.classList.add('hidden');
            }
          }).catch(() => {
            if (loader) loader.classList.add('hidden');
          });
        } else {
          previewLoadTimer = setTimeout(() => {
            if (loader) loader.classList.add('hidden');
          }, 1500);
        }
      } catch (e) {
        if (loader) loader.classList.add('hidden');
      }
      previewLoadTimer = setTimeout(() => {
        if (loader) loader.classList.add('hidden');
      }, 12000);
    };
  }

  document.getElementById('previewModal').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
  refreshIcons();
}

function closePreviewModal() {
  if (previewLoadTimer) clearTimeout(previewLoadTimer);
  const iframe = document.getElementById('previewIframe');
  if (iframe) {
    iframe.src = 'about:blank';
  }
  document.getElementById('previewModal').classList.add('hidden');
  document.body.style.overflow = 'auto';
}

function downloadFromPreview() {
  closePreviewModal();
  if (selectedBook) {
    openDownloadModal(selectedBook.id, encodeURIComponent(selectedBook.title), encodeURIComponent(selectedBook.category), selectedBook.size);
  }
}

